Defaulted container "openmetadata" out of: openmetadata, run-db-migrations (init), convert-truststore (init)
AUTHENTICATION_PROVIDER="custom-oidc"
AUTHENTICATION_CALLBACK_URL=http://20.126.93.87:30585/callback
AUTHENTICATION_CLIENT_TYPE="public"
AUTHENTICATION_AUTHORITY=http://20.126.93.87:30900/realms/stackable-demo
AUTHENTICATION_CLIENT_ID="openmetadata"
AUTHENTICATION_RESPONSE_TYPE="id_token"
---
Defaulted container "openmetadata" out of: openmetadata, run-db-migrations (init), convert-truststore (init)
291:  clientType: ${AUTHENTICATION_CLIENT_TYPE:-public}
294:  responseType: ${AUTHENTICATION_RESPONSE_TYPE:-id_token}
296:  providerName: ${CUSTOM_OIDC_AUTHENTICATION_PROVIDER_NAME:-""}
310:  oidcConfiguration:
311:    id: ${OIDC_CLIENT_ID:-""}
312:    type: ${OIDC_TYPE:-""} # google, azure etc.
313:    secret: ${OIDC_CLIENT_SECRET:-""}
314:    scope: ${OIDC_SCOPE:-"openid email profile"}
315:    discoveryUri: ${OIDC_DISCOVERY_URI:-""}
316:    useNonce: ${OIDC_USE_NONCE:-true}
317:    preferredJwsAlgorithm: ${OIDC_PREFERRED_JWS:-"RS256"}
318:    responseType: ${OIDC_RESPONSE_TYPE:-"code"}
319:    disablePkce: ${OIDC_DISABLE_PKCE:-true}
320:    callbackUrl: ${OIDC_CALLBACK:-"http://localhost:8585/callback"}
321:    serverUrl: ${OIDC_SERVER_URL:-"http://localhost:8585"}
322:    clientAuthenticationMethod: ${OIDC_CLIENT_AUTH_METHOD:-"client_secret_post"}
323:    tenant: ${OIDC_TENANT:-""}
324:    maxClockSkew: ${OIDC_MAX_CLOCK_SKEW:-""}
325:    tokenValidity: ${OIDC_OM_REFRESH_TOKEN_VALIDITY:-"3600"} # in seconds
326:    customParams: ${OIDC_CUSTOM_PARAMS:-}
327:    maxAge: ${OIDC_MAX_AGE:-"0"}
328:    prompt: ${OIDC_PROMPT_TYPE:-"consent"}
329:    sessionExpiry: ${OIDC_SESSION_EXPIRY:-"604800"} #7 days

